window.MGProseData("8475747719a6fe323c14dc7b9b67b6f9c27815446f3d0072258a89f6623ed595",{"html":"\u003cp>记\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>Q\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>r\u003c/mi>\u003c/munderover>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>P\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>Q\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>d\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmtext> 或 \u003c/mtext>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nQ=\\sum_{i=1}^r\\binom{n_i}{2},\\qquad P=Q+d,\n\\qquad\ns_L=\\begin{cases}1,\u0026amp;L=F,\\\\2,\u0026amp;L=K_{-1}\\text{ 或 }K_2.\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb F_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>κ\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmstyle scriptlevel=\"1\">\u003cmtable rowspacing=\"0.1em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>b\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\kappa_i=\n\\sum_{\\substack{a\\in I_i\\\\ b\\notin I_i}}\n\\frac{(A_i)_{ab}}2\\pmod2,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n并令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>κ\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmtext>否则\u003c/mtext>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(1)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\eta=\\begin{cases}1,\u0026amp;\\kappa_i=0\\quad(\\forall i),\\\\\n0,\u0026amp;\\text{否则}.\n\\end{cases}                                                    \\tag{1}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里除以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是有定义的，因为所用条目都是偶数。故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 只依赖于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\\bmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>下面先给出解与计数，再给出固定点、约化和下降结论；证明随各部分给出。\u003c/p>\n\u003ch2>一、可行性、精确基数与真正解的约化\u003c/h2>\n\u003cp>对三个域同时有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1.\u003c/mn>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(2)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\n\\mathscr S_L(A)\\ne\\varnothing\\iff \\eta=1.\n\\quad}                                                        \\tag{2}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n而且，只要任一扩域上有解，就有基域解。\u003c/p>\n\u003cp>对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，精确基数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>η\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi>Q\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(3)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\n|\\mathscr R_{L,M}(A)|\n=\\eta\\,2^{\\,s_LQ(M-1)+r}.\n\\quad}                                                        \\tag{3}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n以及\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi>P\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>η\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi>Q\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi>d\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(4)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\n|\\mathscr C_{L,2}(A)|=2^{s_LP},\\qquad\n|\\mathscr C_{L,M}(A)|\n=\\eta\\,2^{\\,s_LQ(M-1)+r+s_Ld}\\quad(M\\ge3).\n\\quad}                                                        \\tag{4}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 恰在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时为空；\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{L,2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 总非空，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 恰在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时为空。\u003c/p>\n\u003cp>对给定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar U\\in\\mathscr C_{L,M}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，任选其条目提升\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widetilde U\\in M_d(\\mathcal O_L)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。其属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{L,M}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的必要充分条件是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmn>1\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>d\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(5)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\n\\eta=1,\\qquad\n(\\widetilde U^{\\mathsf T}\\widetilde U)_{jj}\n\\equiv1\\pmod{2^{M+1}\\mathcal O_L}\n\\quad(1\\le j\\le d).\n\\quad}                                                        \\tag{5}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这些对角同余与所选提升无关：改变提升 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmi>Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M Z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使对角范数的变化属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M+1}\\mathcal O_L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003ch3>证明：同时正交分解与判准\u003c/h3>\n\u003cp>在由所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 生成的交换的、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-进完备矩阵代数中，反复应用多项式\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>⟼\u003c/mo>\u003cmn>3\u003c/mn>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nx\\longmapsto 3x^2-2x^3\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n可把 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>2\u003c/mn>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\\bmod2=E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 唯一提升为幂等元 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。这个迭代在每一有限精度处都是有限次多项式计算。所得矩阵满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>i\u003c/mi>\u003c/munder>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nP_i^{\\mathsf T}=P_i,\\quad P_i\\equiv E_i\\pmod2,\\quad\nP_iP_j=0\\ (i\\ne j),\\quad \\sum_iP_i=I.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n例如，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_iP_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2M_d(\\mathbb Z_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的幂等元，故它为零。每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 也与所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 交换。\u003c/p>\n\u003cp>对真正解和有限精度候选解，原来的分块条件等价于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi>U\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>U\u003c/mi>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(6)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nP_iU=UE_i\\qquad(\\forall i),                                  \\tag{6}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n有限精度时取相应模数。事实上，正交性给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>U\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>U\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U^{-1}=U^{\\mathsf T}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。若所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>U\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U^{-1}A_iU\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 分块，则所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>U\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U^{-1}P_iU\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 也分块；后者是模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 等于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的幂等元，因此恰为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。反向则由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">[A_j,P_i]=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 得到。\u003c/p>\n\u003cp>令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的第 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 列组成，置 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmo>⋯\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B=[B_1\\ \\cdots\\ B_r]\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsup>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nB\\equiv I\\pmod2,\\qquad\nB^{\\mathsf T}B=\\operatorname{diag}(G_1,\\ldots,G_r),\\qquad\nG_i=(P_i)_{I_i,I_i}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n幂等关系给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G_i\\equiv I\\pmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。进一步，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003cmsub>\u003cmi>κ\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>8\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(7)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\det G_i\\equiv1+4\\kappa_i\\pmod8.                             \\tag{7}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n为验证此式，注意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>×\u003c/mo>\u003cmsubsup>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I_i\\times I_i^c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 子块模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 等于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的对应子块；这可由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">[P_i,A_i]=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和两者模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的形式直接算出。若该子块为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G_i=I+4C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i^2=P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 蕴含\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>X\u003c/mi>\u003cmsup>\u003cmi>X\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\\equiv-XX^{\\mathsf T}\\pmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，从而得到 (7)。\u003c/p>\n\u003cp>当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmn>1\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>8\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\det G_i\\equiv1\\pmod8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，存在\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V_i\\equiv I\\pmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V_i^{\\mathsf T}G_iV_i=I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。具体地，写\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G_i=I+4C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。先选一个对称的零对角 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0,1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 矩阵 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使其各行和模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 分别等于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的对角元；这样的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 存在，恰因为这些对角元之和为零。以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I+2X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 变换后，对角元均为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\\bmod8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，非对角元均为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\\bmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。随后用系数属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\\mathbb Z_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的正交消元将其对角化；对角元仍为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\\bmod8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，因而都是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb Z_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中的平方。缩放这些对角元即得所需 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>反之，即使只要求模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的扩域解，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmn>5\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\det G_i\\equiv5\\bmod8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 也不可能。确切地说，若\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmn>1\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x=a+b\\theta_\\mu\\equiv1\\pmod{2\\mathcal O_\\mu}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为有理数，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为奇数、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>b\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">b\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为偶数；由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\theta_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 系数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>a\u003c/mi>\u003cmi>b\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2ab\\equiv0\\bmod8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">b\\equiv0\\bmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，于是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≡\u003c/mo>\u003cmn>1\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x^2\\equiv1\\bmod8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，不可能为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>5\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">5\\bmod8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。基域情形同样成立。\u003c/p>\n\u003cp>这证明了 (2)，也证明 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{L,M}=\\varnothing\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）。当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，上述构造给出一个\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>T\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T\\in\\mathscr S_F(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>T\u003c/mi>\u003cmunderover>\u003cmo>∏\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>r\u003c/mi>\u003c/munderover>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>V\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">GL\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmi>V\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmi>V\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>V\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(8)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\mathscr S_L(A)\n=T\\prod_{i=1}^r\n\\{V\\in\\operatorname{GL}_{n_i}(\\mathcal O_L):\n V\\equiv I\\pmod2,\\ V^{\\mathsf T}V=I\\},                       \\tag{8}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中积理解为分块对角矩阵。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\\bmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 仍给出模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的正交分块标架；所以模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 候选集总非空。\u003c/p>\n\u003ch3>证明：有限计数与判据 (5)\u003c/h3>\n\u003cp>对单块秩 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，写 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q=\\binom n2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>Y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U=I+2Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。正交方程等价于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left right left\" columnspacing=\"0em 1em 0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>Y\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>Y\u003c/mi>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>k\u003c/mi>\u003c/munder>\u003cmsub>\u003cmi>Y\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmsub>\u003cmi>Y\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi>f\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>Y\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>k\u003c/mi>\u003c/munder>\u003cmsubsup>\u003cmi>Y\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(9)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{aligned}\ng_{ij}(Y)\u0026amp;=Y_{ij}+Y_{ji}\n            +2\\sum_kY_{ki}Y_{kj}=0 \u0026amp;\u0026amp;(i\u0026lt;j),\\\\\nf_i(Y)\u0026amp;=Y_{ii}+\\sum_kY_{ki}^2=0. \u0026amp;\u0026amp;\n\\end{aligned}                                                \\tag{9}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的候选集中，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_{ij}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 要模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为零，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>f\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 只须模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M-2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为零。\u003c/p>\n\u003cp>对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal O_F/2=\\mathbb F_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；对两个扩域，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>t\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\mathcal O_\\mu/2\\mathcal O_\\mu\\simeq\n\\mathbb F_2[t]/(t^2).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n例如可分别取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t=1+\\theta_{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t=\\theta_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。记到剩余域 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb F_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的映射为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\rho\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。方程 (9) 模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的条件是：\u003c/p>\n\u003cul>\n\u003cli>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Y\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>Y\u003c/mi>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y_{ij}=Y_{ji}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003c/li>\n\u003cli>每个对角元 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Y\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y_{ii}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 或 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003c/li>\n\u003cli>每个顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>Y\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sum_{j\\ne i}\\rho(Y_{ij})=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ul>\n\u003cp>最后一组是完全图边变量的偶度条件，秩为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。把下三角条目作为自由参数时，方程 (9) 对上三角及对角未知量的 Jacobian 模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为单位矩阵。因此，完备环上的 Hensel 提升表明：任何满足上述模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 条件的选择，按精度唯一提升未知的上三角及对角条目。\u003c/p>\n\u003cp>于是单块真正解在模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的像有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n2^{\\,s_Lq(M-1)+1}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n个。模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 候选集只要求 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y\\bmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对称，故有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{s_L(q+n)}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 个；当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，相对真正解像，每个对角未知量还多一个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal O_L/2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的自由层，故候选数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi>n\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n2^{\\,s_Lq(M-1)+1+s_Ln}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对各块相乘即得 (3)、(4)。同一个 Hensel 提升论证也说明：候选类能提升为真正解，当且仅当 (9) 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>f\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在多一层精度上为零；这正是 (5)。结合 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 得到所述全局判据。\u003c/p>\n\u003ch2>二、Galois 固定类、轨道及逐层约化\u003c/h2>\n\u003cp>以下固定一个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，写\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>θ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>σ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>ϵ\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi>θ\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\theta=\\theta_\\mu,\\qquad \\sigma=\\sigma_\\mu,\\qquad\n\\epsilon_M=2^{M-1}\\theta\\pmod{2^M\\mathcal O_\\mu}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left\" columnspacing=\"0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Sym\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi mathvariant=\"normal\">b\u003c/mi>\u003cmi mathvariant=\"normal\">l\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmi>D\u003c/mi>\u003cmtext> 分块对角且 \u003c/mtext>\u003cmsup>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Alt\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi mathvariant=\"normal\">b\u003c/mi>\u003cmi mathvariant=\"normal\">l\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Sym\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi mathvariant=\"normal\">b\u003c/mi>\u003cmi mathvariant=\"normal\">l\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{aligned}\n\\operatorname{Sym}_{\\rm bl}\n \u0026amp;=\\{D\\in M_d(\\mathbb F_2):D\\text{ 分块对角且 }D^{\\mathsf T}=D\\},\\\\\n\\operatorname{Alt}_{\\rm bl}\n \u0026amp;=\\{D\\in\\operatorname{Sym}_{\\rm bl}:D_{jj}=0\\quad\\forall j\\}.\n\\end{aligned}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它们的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb F_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-维数分别为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>P\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。下式中的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可任取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0,1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 整数提升；结果不依赖提升，因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>ϵ\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\\epsilon_M=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003ch3>固定矩阵类的具体形式\u003c/h3>\n\u003ch1>对所有输入和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有不相交的唯一表示\n[\n\\boxed{\\quad\n\\mathscr C_{K_\\mu,M}(A)^\\sigma\u003c/h1>\n\u003cp>\\mathscr C_{F,M}(A)+\\epsilon_M\\operatorname{Sym}_{\\rm bl}.\n\\quad}                                                        \\tag{10}\n]\u003c/p>\n\u003ch1>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都为空。以下假设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，以及对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>μ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(\\mu,M)=(2,2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有\n[\n\\boxed{\\quad\n\\mathscr R_{K_\\mu,M}(A)^\\sigma\u003c/h1>\n\u003ch1>\\mathscr R_{F,M}(A)+\\epsilon_M\\operatorname{Alt}\u003cem>{\\rm bl}.\n\\quad}                                                        \\tag{11}\n]\n唯一需要单独写出的情形是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>μ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(\\mu,M)=(-1,2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U_0\\in\\mathscr C_{F,2}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>o\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsubsup>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\no_j(U_0)=\n\\frac{(\\widetilde U_0^{\\mathsf T}\\widetilde U_0)_{jj}-1}{4}\n\\pmod2,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widetilde U_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是任意整数矩阵提升。则\n[\n\\boxed{\\quad\n\\mathscr R\u003c/em>{K_{-1},2}(A)^\\sigma\u003c/h1>\n\u003cp>\\left{U_0+2\\theta_{-1}D:\n\\begin{array}{l}\nU_0\\in\\mathscr C_{F,2}(A),\u003cbr>\nD\\in\\operatorname{Alt}\u003cem>{\\rm bl},\\[2pt]\no_j(U_0)=\\displaystyle\\sum_kD\u003c/em>{kj}\\quad(\\forall j)\n\\end{array}\\right}.\n\\quad}                                                        \\tag{12}\n]\n和在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb F_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中计算。\u003c/p>\n\u003cp>特别地，所有模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 候选类及真正解的模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 类都由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 固定。并且，对于每个精度，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>∩\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>∩\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(13)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\mathscr C_{K_\\mu,M}\\cap M_d(\\mathbb Z_2/2^M)=\\mathscr C_{F,M},\n\\qquad\n\\mathscr R_{K_\\mu,M}\\cap M_d(\\mathbb Z_2/2^M)=\\mathscr R_{F,M}.\n                                                                    \\tag{13}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch1>这些公式也给出固定点数：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>σ\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>Q\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>η\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>Q\u003c/mi>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(14)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\n|\\mathscr R_{K_\\mu,M}(A)^\\sigma|\n=2^Q|\\mathscr R_{F,M}(A)|\n=\\eta\\,2^{QM+r},\n\\quad}                                                        \\tag{14}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n[\n\\boxed{\\quad\n|\\mathscr C_{K_\\mu,M}(A)^\\sigma|\n=2^P|\\mathscr C_{F,M}(A)|\u003c/h1>\n\u003ch1>\\begin{cases}\n2^{2P},\u0026amp;M=2,\\\n\\eta,2^{QM+r+2d},\u0026amp;M\\ge3.\n\\end{cases}\n\\quad}                                                        \\tag{15}\n]\n由两元素群的轨道计数公式，轨道数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">#\u003c/mi>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmi>η\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>Q\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>Q\u003c/mi>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(16)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\n\\#\\bigl(\\mathscr R_{K_\\mu,M}(A)/\\langle\\sigma\\rangle\\bigr)\n=\\frac{\\eta}{2}\n \\left(2^{2Q(M-1)+r}+2^{QM+r}\\right),\n\\quad}                                                        \\tag{16}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n以及\n[\n\\boxed{\\quad\n#\\bigl(\\mathscr C_{K_\\mu,M}(A)/\\langle\\sigma\\rangle\\bigr)\u003c/h1>\n\u003cp>\\begin{cases}\n2^{2P},\u0026amp;M=2,\\[2pt]\n\\displaystyle\\frac{\\eta}{2}\n\\left(2^{2Q(M-1)+r+2d}+2^{QM+r+2d}\\right),\u0026amp;M\\ge3.\n\\end{cases}\n\\quad}                                                        \\tag{17}\n]\u003c/p>\n\u003cp>\u003cstrong>证明。\u003c/strong> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal O_\\mu/2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-固定元唯一写成\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>ϵ\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmi>b\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>a\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>b\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\na+\\epsilon_M b,\\qquad a\\in\\mathbb Z_2/2^M,\\quad b\\in\\mathbb F_2,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>ϵ\u003c/mi>\u003cmi>M\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\epsilon_M^2=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。将此写法逐条目代入 (6) 及正交方程：由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>2\u003c/mn>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i\\bmod2=E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>2\u003c/mn>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\\bmod2=I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ϵ\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\epsilon_M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的系数必须分块对角且对称，这证明 (10)。\u003c/p>\n\u003cp>再用 (5) 检查列范数。对于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>ϵ\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U=U_0+\\epsilon_MD\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>U\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>U\u003c/mi>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsubsup>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmi>θ\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsubsup>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmi>D\u003c/mi>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi>μ\u003c/mi>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>k\u003c/mi>\u003c/munder>\u003cmsubsup>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n(U^{\\mathsf T}U)_{jj}\n=(U_0^{\\mathsf T}U_0)_{jj}\n+2^M\\theta\\,(U_0^{\\mathsf T}D)_{jj}\n+2^{2M-2}\\mu\\sum_kD_{kj}^2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时最后一项消失；其余两项给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D_{jj}=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U_0\\in\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即 (11)。当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，最后一项可能贡献 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmi>μ\u003c/mi>\u003cmsub>\u003cmo>∑\u003c/mo>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\\mu\\sum_kD_{kj}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，于是分别得到 (11) 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 情形和 (12)。模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的所有类固定，是因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\\equiv I\\bmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 蕴含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>U\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>U\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma(U)-U\\equiv0\\bmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。计数和轨道公式随之得到。\u003c/p>\n\u003ch3>从 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M+1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的像与纤维\u003c/h3>\n\u003cp>下面表中的最后一列是\u003cstrong>每个非空纤维\u003c/strong>的大小；当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时所有这些约化映射的像均为空，因此没有非空纤维。\u003c/p>\n\u003cp>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center center\" columnlines=\"solid solid\" columnspacing=\"1em\" rowlines=\"solid none none none\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmtext>约化映射\u003c/mtext>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmtext>像\u003c/mtext>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmtext>每个非空纤维的大小\u003c/mtext>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi>Q\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi>P\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>σ\u003c/mi>\u003c/msubsup>\u003cmo>→\u003c/mo>\u003cmsubsup>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmi>σ\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>Q\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>σ\u003c/mi>\u003c/msubsup>\u003cmo>→\u003c/mo>\u003cmsubsup>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmi>σ\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>P\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(18)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{array}{c|c|c}\n\\text{约化映射}\u0026amp;\\text{像}\u0026amp;\\text{每个非空纤维的大小}\\\\ \\hline\n\\mathscr R_{L,M+1}\\to\\mathscr R_{L,M}\n \u0026amp;\\mathscr R_{L,M}\u0026amp;2^{s_LQ}\\\\\n\\mathscr C_{L,M+1}\\to\\mathscr C_{L,M}\n \u0026amp;\\mathscr R_{L,M}\u0026amp;2^{s_LP}\\\\\n\\mathscr R_{K_\\mu,M+1}^{\\sigma}\\to\n  \\mathscr R_{K_\\mu,M}^{\\sigma}\n \u0026amp;\\mathscr R_{F,M}\u0026amp;2^{2Q}\\\\\n\\mathscr C_{K_\\mu,M+1}^{\\sigma}\\to\n  \\mathscr C_{K_\\mu,M}^{\\sigma}\n \u0026amp;\\mathscr R_{F,M}\u0026amp;2^{2P}\n\\end{array}                                                   \\tag{18}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里基域集合按题意嵌入相应扩域集合。\u003c/p>\n\u003cp>前两行由 (5) 得到：精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M+1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的候选类约化后满足精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的真正提升判据；反之，真正解显然提供提升。后两行中，固定类的非有理部分在约化时消失，再用前两行的基域版本即可。用 (3)、(4)、(14)、(15) 取基数之比，或用所述群陪集结构，得到全部纤维大小。\u003c/p>\n\u003cp>固定类中，以下三个条件等价：\u003c/p>\n\u003col>\n\u003cli>它是某个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-固定真正解的模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 类；\u003c/li>\n\u003cli>它能作为一条逐层相容的固定类序列在精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的分量；\u003c/li>\n\u003cli>它属于嵌入的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ol>\n\u003cp>这里无论固定类最初属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 还是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，结论相同。事实上，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-固定真正解恰是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr S_F(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而表 (18) 已说明即使只向上提升一个固定层，像也恰为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003ch2>三、下降的最优精度\u003c/h2>\n\u003cp>满足题目第三问的最大整数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>Q\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmtext>即所有 \u003c/mtext>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>Q\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(19)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\nN_{\\max}=\n\\begin{cases}\nM,\u0026amp;Q=0\\quad(\\text{即所有 }n_i=1),\\\\\nM-1,\u0026amp;Q\u0026gt;0.\n\\end{cases}\n\\quad}                                                        \\tag{19}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>对给定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A,U\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，唯一写\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>b\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nU=a+\\theta_\\mu b,\\qquad a,b\\in M_d(\\mathbb Z_2).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n题设的近似固定条件等价于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(20)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nb\\in2^{M-1}M_d(\\mathbb Z_2).                                \\tag{20}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对于这个给定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，能取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N=M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的必要充分条件是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmi>b\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(21)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad b\\in2^MM_d(\\mathbb Z_2).\\quad}                  \\tag{21}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n实际精确下降 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\\in\\mathscr S_F(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 则等价于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">b=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>若所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_i=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有更强结论：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmtext>作为矩阵集合\u003c/mtext>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(22)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\n\\mathscr S_{K_\\mu}(A)=\\mathscr S_F(A)\n\\quad\\text{作为矩阵集合}.\n\\quad}                                                        \\tag{22}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n若有某个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_i\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则即使要求任意预定的有限精度近似固定，也不能保证精确下降。\u003c/p>\n\u003ch3>证明及统一最优性构造\u003c/h3>\n\u003cp>若给定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 存在，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以存在基域真正解。由正交性和 (6)，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>a\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>μ\u003c/mi>\u003cmsup>\u003cmi>b\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>b\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi>a\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\na^{\\mathsf T}a+\\mu b^{\\mathsf T}b=I,\\qquad\nP_i a=aE_i.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，由 (20) 可知 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\\bmod2^{M-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是基域候选类，而且其列范数模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 (5)，它属于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M-1}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，任意基域真正解都与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 同余。因此总可下降到精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>b\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">b\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可被 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 整除，同样的论证和 (5) 给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\\bmod2^M\\in\\mathscr R_{F,M}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。反过来，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 同余于有理矩阵，则按 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>⊕\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal O_\\mu=\\mathbb Z_2\\oplus\\mathbb Z_2\\theta_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的唯一分解，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>b\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">b\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 必可被 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 整除。这证明 (21)。\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Q\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由 (8) 和域中的恒等式 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>v\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>⇒\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>±\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v^2=1\\Rightarrow v=\\pm1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得到 (22)。\u003c/p>\n\u003cp>现在设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Q\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，在某块内选两个坐标，并取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i=E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，统一定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmi>π\u003c/mi>\u003cmi>μ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\pi_\\mu=\\begin{cases}1+\\theta_{-1},\u0026amp;\\mu=-1,\\\\\n\\theta_2,\u0026amp;\\mu=2,\\end{cases}\n\\qquad\n\\lambda_\\mu=\\pi_\\mu^2/2=\n\\begin{cases}\\theta_{-1},\u0026amp;\\mu=-1,\\\\1,\u0026amp;\\mu=2.\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>b\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nb_M=2^{M-1}\\pi_\\mu.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由 Hensel 引理，方程\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nx+x^2=-2^{2M-3}\\lambda_\\mu\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n有唯一满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\\equiv0\\bmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的解；令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a_M=1+2x\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>a\u003c/mi>\u003cmi>M\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>b\u003c/mi>\u003cmi>M\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmn>1\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\na_M^2+b_M^2=1,\\qquad\na_M\\equiv1\\pmod{2^{2M-2}}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在所选两个坐标上放置\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>b\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi>b\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\begin{pmatrix}a_M\u0026amp;-b_M\\\\ b_M\u0026amp;a_M\\end{pmatrix},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其余坐标放恒等矩阵，得到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U_M\\in\\mathscr S_{K_\\mu}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。它满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\sigma(U_M)\\equiv U_M\\pmod{2^M},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n但 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>b\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">b_M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\theta_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-系数恰为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以它不可能模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 同余于任何基域矩阵。这对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都给出实际反例，证明 (19) 的最优性，也证明有非平凡块时不能保证精确下降。\u003c/p>\n\u003ch2>四、其他否定情形的具体例子\u003c/h2>\n\u003cul>\n\u003cli>\n\u003cp>\u003cstrong>合法输入可以不可行。\u003c/strong> 取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r=2,n_1=n_2=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>5\u003c/mn>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>4\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>5\u003c/mn>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>4\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nA_1=\\frac15\\begin{pmatrix}1\u0026amp;2\\\\2\u0026amp;4\\end{pmatrix},\n\\qquad\nA_2=\\frac15\\begin{pmatrix}4\u0026amp;-2\\\\-2\u0026amp;1\\end{pmatrix}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它们是正交互补的对称幂等元，满足全部输入条件，但\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>κ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>κ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\kappa_1=\\kappa_2=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此三个域上均无真正解，且精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的候选集为空。不过\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>5\u003c/mn>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\frac15\\begin{pmatrix}1\u0026amp;-2\\\\2\u0026amp;1\\end{pmatrix}\\pmod4\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n是模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 候选类。这也给出模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 候选类不能提升的例子。\u003c/p>\n\u003c/li>\n\u003cli>\n\u003cp>\u003cstrong>可行输入上，固定候选类也可能没有真正提升。\u003c/strong> 取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i=E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和任一坐标 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nI+2^{M-1}\\theta_\\mu E_{jj}\\pmod{2^M}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmi>σ\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{K_\\mu,M}^{\\sigma}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，但列范数不满足 (5)，故不属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{K_\\mu,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有理类\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I+2^{M-1}E_{jj}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 也给出基域候选类不能提升的例子。若某块秩至少为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的基域例子可取该块中的\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmstyle scriptlevel=\"1\">\u003cmtable rowspacing=\"0.1em\" columnspacing=\"0.2778em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\left(\\begin{smallmatrix}1\u0026amp;2\\\\2\u0026amp;1\\end{smallmatrix}\\right)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003c/li>\n\u003cli>\n\u003cp>\u003cstrong>固定真正解类未必来自固定真正解。\u003c/strong> 当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Q\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，上述 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U_M\\bmod2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是固定的真正解类，却不属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以不能提升为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-固定真正解，也不能继续作为固定类提升到下一层。对于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，同一构造中的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U_{M-1}\\bmod2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 还给出不被 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 固定的真正解类。特别地，在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>μ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(\\mu,M)=(-1,2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，该构造的有理部分模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmstyle scriptlevel=\"1\">\u003cmtable rowspacing=\"0.1em\" columnspacing=\"0.2778em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\left(\\begin{smallmatrix}1\u0026amp;2\\\\2\u0026amp;1\\end{smallmatrix}\\right)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，它不是基域真正解类；这具体展示了公式 (12) 中的扭曲项不可省去。\u003c/p>\n\u003c/li>\n\u003c/ul>\n","source":"assets/content/8475747719a6fe323c14dc7b9b67b6f9c27815446f3d0072258a89f6623ed595.html"});
